import { useMemo, useState } from 'react';
import * as d3 from 'd3';

// ---- inlined from arcDiagram ----
type LanguageNode = { id: string; year: number; group: string };
type LanguageLink = { source: string; target: string };

/** Sorted by first-release year (ties alphabetical) — this order IS the diagram's y-axis. */
const languageNodes: LanguageNode[] = [
  { id: 'Fortran', year: 1957, group: 'imperative' },
  { id: 'Algol60', year: 1958, group: 'imperative' },
  { id: 'Lisp', year: 1958, group: 'functional' },
  { id: 'Simula', year: 1967, group: 'oo' },
  { id: 'Algol68', year: 1968, group: 'imperative' },
  { id: 'Pascal', year: 1970, group: 'imperative' },
  { id: 'C', year: 1972, group: 'imperative' },
  { id: 'Prolog', year: 1972, group: 'logic' },
  { id: 'Smalltalk', year: 1972, group: 'oo' },
  { id: 'ML', year: 1973, group: 'functional' },
  { id: 'Scheme', year: 1975, group: 'functional' },
  { id: 'C++', year: 1985, group: 'oo' },
  { id: 'Erlang', year: 1986, group: 'functional' },
  { id: 'Perl', year: 1987, group: 'scripting' },
  { id: 'Haskell', year: 1990, group: 'functional' },
  { id: 'Python', year: 1991, group: 'scripting' },
  { id: 'Java', year: 1995, group: 'oo' },
  { id: 'JavaScript', year: 1995, group: 'scripting' },
  { id: 'PHP', year: 1995, group: 'scripting' },
  { id: 'Ruby', year: 1995, group: 'scripting' },
  { id: 'OCaml', year: 1996, group: 'functional' },
  { id: 'C#', year: 2000, group: 'oo' },
  { id: 'Scala', year: 2003, group: 'functional' },
  { id: 'Go', year: 2009, group: 'imperative' },
  { id: 'Rust', year: 2010, group: 'imperative' },
  { id: 'Kotlin', year: 2011, group: 'oo' },
  { id: 'TypeScript', year: 2012, group: 'scripting' },
  { id: 'Swift', year: 2014, group: 'oo' }
];

/** Well-known lineage: source's design directly shaped target's. Not exhaustive. */
const languageLinks: LanguageLink[] = [
  { source: 'Fortran', target: 'Algol60' },
  { source: 'Algol60', target: 'Algol68' },
  { source: 'Algol60', target: 'Pascal' },
  { source: 'Algol68', target: 'C' },
  { source: 'Lisp', target: 'Scheme' },
  { source: 'Lisp', target: 'ML' },
  { source: 'Simula', target: 'Smalltalk' },
  { source: 'Simula', target: 'C++' },
  { source: 'C', target: 'C++' },
  { source: 'C', target: 'Perl' },
  { source: 'C', target: 'Python' },
  { source: 'C', target: 'JavaScript' },
  { source: 'C', target: 'Go' },
  { source: 'C++', target: 'Java' },
  { source: 'C++', target: 'C#' },
  { source: 'C++', target: 'Rust' },
  { source: 'ML', target: 'Haskell' },
  { source: 'ML', target: 'OCaml' },
  { source: 'Scheme', target: 'JavaScript' },
  { source: 'Smalltalk', target: 'Python' },
  { source: 'Smalltalk', target: 'Ruby' },
  { source: 'Java', target: 'JavaScript' },
  { source: 'Java', target: 'C#' },
  { source: 'Java', target: 'Scala' },
  { source: 'Java', target: 'Kotlin' },
  { source: 'Perl', target: 'PHP' },
  { source: 'Perl', target: 'Ruby' },
  { source: 'Python', target: 'Swift' },
  { source: 'Ruby', target: 'Swift' },
  { source: 'Haskell', target: 'Scala' },
  { source: 'Haskell', target: 'Rust' },
  { source: 'Haskell', target: 'Swift' },
  { source: 'OCaml', target: 'Rust' },
  { source: 'OCaml', target: 'Scala' },
  { source: 'Pascal', target: 'Go' },
  { source: 'JavaScript', target: 'TypeScript' },
  { source: 'C#', target: 'TypeScript' },
  { source: 'Prolog', target: 'Erlang' },
  { source: 'Scala', target: 'Kotlin' }
];

const MARGIN_TOP = 20;
const MARGIN_BOTTOM = 20;
const MARGIN_RIGHT = 16;
const MAX_ROW_HEIGHT = 16;
const LABEL_GAP = 8;

/** Nodes in the order they stack down the axis, and the links between their ids. */
export type Data = {
  nodes: { id: string; year: number; group: string }[];
  links: { source: string; target: string }[];
};

const DEMO: Data = { nodes: languageNodes, links: languageLinks };

export default function ArcDiagram({ data = DEMO, width }: { data?: Data; width: number }) {
  const [hovered, setHovered] = useState<string | null>(null);

  const groups = useMemo(() => Array.from(new Set(data.nodes.map((n) => n.group))).sort(), [data]);
  const color = useMemo(
    () => d3.scaleOrdinal<string, string>().domain(groups).range(d3.schemeObservable10),
    [groups]
  );
  const groupOf = useMemo(() => new Map(data.nodes.map((n) => [n.id, n.group])), [data]);
  const orderedIds = useMemo(() => data.nodes.map((n) => n.id), [data]);
  const positionOf = useMemo(() => new Map(orderedIds.map((id, i) => [id, i])), [orderedIds]);

  // The widest link (in row count) sets how much horizontal room an arc needs, which
  // is what actually has to fit inside `width` — the row spacing gives way, not it.
  const maxSpan = useMemo(
    () =>
      d3.max(data.links, (l) => Math.abs((positionOf.get(l.source) ?? 0) - (positionOf.get(l.target) ?? 0))) ?? 1,
    [data, positionOf]
  );

  const marginLeft = Math.min(150, Math.max(70, width * 0.28));
  const innerWidth = Math.max(width - marginLeft - MARGIN_RIGHT, 40);
  const step = Math.max(9, Math.min(MAX_ROW_HEIGHT, (innerWidth * 2) / maxSpan));
  const height = (orderedIds.length - 1) * step + MARGIN_TOP + MARGIN_BOTTOM;

  const y = useMemo(
    () => d3.scalePoint(orderedIds, [MARGIN_TOP, height - MARGIN_BOTTOM]),
    [orderedIds, height]
  );

  function sameGroup(link: Data['links'][number]) {
    const g1 = groupOf.get(link.source);
    const g2 = groupOf.get(link.target);
    return g1 === g2 ? g1 : undefined;
  }

  function arcPath(link: Data['links'][number]) {
    const y1 = y(link.source) ?? 0;
    const y2 = y(link.target) ?? 0;
    const r = Math.abs(y2 - y1) / 2;
    const sweep = y1 < y2 ? 1 : 0;
    return `M${marginLeft},${y1} A${r},${r} 0 0,${sweep} ${marginLeft},${y2}`;
  }

  const connected = useMemo(() => {
    if (!hovered) return null;
    const ids = new Set<string>([hovered]);
    data.links.forEach((l) => {
      if (l.source === hovered) ids.add(l.target);
      if (l.target === hovered) ids.add(l.source);
    });
    return ids;
  }, [data, hovered]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Arc diagram of programming language influence, ordered chronologically by first release"
    >
      <g fill="none" strokeWidth={1.4}>
        {data.links.map((l) => {
          const isActive = hovered !== null && (l.source === hovered || l.target === hovered);
          const group = sameGroup(l);
          return (
            <path
              key={`${l.source}-${l.target}`}
              d={arcPath(l)}
              stroke={group ? color(group) : 'var(--muted)'}
              strokeOpacity={hovered === null ? 0.55 : isActive ? 0.95 : 0.08}
            />
          );
        })}
      </g>

      {data.nodes.map((node) => {
        const cy = y(node.id) ?? 0;
        const isPrimary = node.id === hovered;
        const isSecondary = connected?.has(node.id) && !isPrimary;
        const isDimmed = connected !== null && !connected.has(node.id);
        return (
          <g key={node.id} transform={`translate(${marginLeft},${cy})`}>
            <rect
              x={-marginLeft}
              y={-step / 2}
              width={marginLeft + 32}
              height={step}
              fill="transparent"
              onPointerEnter={() => setHovered(node.id)}
              onPointerLeave={() => setHovered(null)}
            >
              <title>{`${node.id} (${node.year}) — ${node.group}`}</title>
            </rect>
            <text
              x={-LABEL_GAP}
              dy="0.35em"
              textAnchor="end"
              fontFamily="sans-serif"
              fontSize={10}
              fontWeight={isPrimary ? 'bold' : undefined}
              fill={isPrimary || isSecondary ? 'var(--text)' : isDimmed ? 'var(--muted)' : 'var(--text)'}
              opacity={isDimmed ? 0.4 : 1}
              pointerEvents="none"
            >
              {node.id}
            </text>
            <circle r={3} fill={color(node.group)} opacity={isDimmed ? 0.4 : 1} pointerEvents="none" />
          </g>
        );
      })}
    </svg>
  );
}
